#!/usr/bin/env bash
# recipes/crate-futures-task--0-3-30/build.sh -- stage the futures-task 0.3.30 crate as
# an entry of the cargo directory source share/cargo/crates/ (docs/rust-crates.md).
# Generated by tools/make_crate_packages.py.
set -euo pipefail
dest="${CVC_INSTALL_DIR}/share/cargo/crates/futures-task-0.3.30"
mkdir -p "${dest}"
cp -R "${CVC_SOURCE_DIR}/." "${dest}/"
